                       extra_member: Optional[list] = None,
                       extra_buildtool: Optional[list] = None,
                       extra_test: Optional[list] = None) -> None:
    dep_lines = "\n".join(f"  <depend>{d}</depend>" for d in deps)
    exec_lines = ""
    if extra_exec:
        exec_lines = "\n" + "\n".join(
            f"  <exec_depend>{d}</exec_depend>" for d in extra_exec)
    buildtool_lines = ""
    if extra_buildtool:
